import{_ as o,c as t,o as i,a2 as a}from"./chunks/framework.CFHYvIe4.js";const h=JSON.parse('{"title":"What is S1API?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1756461828000}'),s={name:"guide/index.md"};function n(r,e,l,d,c,p){return i(),t("div",null,e[0]||(e[0]=[a('<h1 id="what-is-s1api" tabindex="-1">What is S1API? <a class="header-anchor" href="#what-is-s1api" aria-label="Permalink to &quot;What is S1API?&quot;">​</a></h1><p>S1API is an open source collaboration project to help standardize Schedule One modding processes. The goal is to provide a standard place for common functionalities so you can focus on making content versus reverse engineering the game.</p><blockquote><p><strong>Note:</strong> If you are just looking to mod your game, please refer to the releases on mod repositories such as Thunderstore and Nexus Mods. This documentation is intended for developers.</p></blockquote><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>S1API serves as a compatibility layer between Mono and Il2Cpp versions of Schedule One, allowing mod developers to:</p><ul><li>Create content that works across different game builds</li><li>Utilize common game functions without using assemblies directly</li><li>Develop in a familiar Managed environment regardless of target build</li></ul><h2 id="what-s1api-provides" tabindex="-1">What S1API Provides <a class="header-anchor" href="#what-s1api-provides" aria-label="Permalink to &quot;What S1API Provides&quot;">​</a></h2><ul><li><strong>Content Creation</strong>: Tools for creating new game elements (quests, NPCs, etc.)</li><li><strong>Data Management</strong>: Easy-to-use abstractions for save/load functionality</li><li><strong>Game Functions</strong>: Simplified access to common game functions</li><li><strong>Cross-Compatibility</strong>: Build once, deploy anywhere approach</li><li><strong>Community Support</strong>: Collaborative environment for modders</li></ul><h2 id="how-it-s-designed-to-work" tabindex="-1">How It&#39;s Designed to Work <a class="header-anchor" href="#how-it-s-designed-to-work" aria-label="Permalink to &quot;How It&#39;s Designed to Work&quot;">​</a></h2><p>S1API is designed to compile for Mono and Il2Cpp separately. Mod users install the version applicable to their preferred build.</p><p>Mod developers can develop their mods on either Mono or Il2Cpp without having to step into the Il2Cpp environment directly. Note that if you utilize Il2Cpp-specific functionality within your mod, you may lose cross compatibility.</p><p>S1API is also designed to be a tag-along. If you want to create custom content specific to Mono or Il2Cpp, S1API can still assist with common repetitive tasks.</p><h2 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h2><p>S1API is designed to cover common use cases but has some limitations:</p><ul><li>It will not cover every possible modding scenario</li><li>Advanced functionality may still require direct assembly references</li><li>Some game-specific features might not be fully abstracted</li></ul><h2 id="want-to-contribute" tabindex="-1">Want to Contribute? <a class="header-anchor" href="#want-to-contribute" aria-label="Permalink to &quot;Want to Contribute?&quot;">​</a></h2><p>This is a massive project with many different areas to specialize in. If you&#39;re interested in contributing, please refer to the <a href="/S1API-docs/contributing/">Contributing</a> page for guidance on code standards and the contribution process.</p>',17)]))}const m=o(s,[["render",n]]);export{h as __pageData,m as default};
